"""Render an honest summary of executed verification records."""
from pathlib import Path
import json,html
import sys;sys.path.insert(0,str(Path(__file__).resolve().parent));import shell
ROOT=Path(__file__).resolve().parents[1]
# Evidence is part of the website: it is linked from the site and served with
# it. `validation/` at the repository root keeps only what is never published —
# the visual baselines this report does not link.
EVIDENCE=ROOT/'website/verification'
def read(name):return json.loads((EVIDENCE/name).read_text())
tokens=read('token-checks.json');browser=read('browser-checks.json');exports=read('export-checks.json')
text_pairs=[x['ratio'] for x in tokens['results'] if x['minimum']==4.5]
artifact=read('artifact-checks.json') if (EVIDENCE/'artifact-checks.json').exists() else None
artifact_html=f'<li>{artifact["htmlPages"]} HTML pages and {artifact["localLinksAndAssets"]} local links/assets checked; {len(artifact["errors"])} errors.</li>' if artifact else ''
artifact_link='<li><a href="artifact-checks.json">Static artifact checks</a></li>' if artifact else ''
motion=read('motion-runtime-checks.json') if (EVIDENCE/'motion-runtime-checks.json').exists() else None
motion_html=f'<li>Motion 13.4.0 and GSAP 3.15.0: {motion["passed"]} real-browser contracts passed, {motion["failed"]} failed, covering all {motion["recipes"]} recipes and the material signatures.</li>' if motion else ''
motion_link='<li><a href="motion-runtime-checks.json">Real-engine motion contracts</a> · <a href="motion-static-checks.json">Static motion contracts</a></li>' if motion else ''
rows=''.join('<li>'+html.escape(item['check'])+'</li>' for item in browser['checks'] if item['check']!='palette and material rendering')
content=f'''<h1>Verification and limits</h1><p>Checks executed September 17, 2026. This is evidence about this reference package, not production application readiness or complete WCAG conformance.</p><h2>Executed checks</h2><ul><li>{tokens['checks']} solid-pair and bounded composite contrast cases; {len(tokens['failures'])} failures. Minimum normal-text result: {min(text_pairs):.2f}:1. Essential non-text cases use their separate 3:1 threshold.</li><li>All six palettes in both modes, scene navigation, appearance controls, preference restoration, reduced effects and keyboard dialog focus behavior exercised in the browser.</li><li>Responsive scenes at 320px and 390px, plus final material studies at 320px, checked for page overflow.</li><li>CSS and JSON files actually downloaded through the UI and inspected for the current configuration, both modes and updated material parameters.</li><li>Plastic opacity and inactive fallback, 40px Frost diffusion, and Resin appearance checked.</li><li>Five immutable source specification copies verified against their SHA-256 manifests and the original files. The manifest and the copies are kept in the repository rather than published.</li>{artifact_html}{motion_html}</ul><h2>Scope and limitations</h2><p>The contrast model checks Resin/Haze control labels with optical sheen beneath the protective fill, declared solid pairs, foundation combinations, 80%/79% content composites and RGB-corner backdrops with the fixed 20% Resin fill and mode-specific Stone fill and optical sheen. It is not a pixel-level audit of every possible image or layout. Native materials, screen readers, full zoom/assistive workflows, and cross-browser coverage remain adoption checks. Forced-colors rendering was tested in both high-contrast palettes and is recorded in the captures below.</p><p>The HTTP preview was tested. The browser's URL policy blocked a direct file-URL test; no workaround was attempted. The files use relative local assets, but direct-file execution is not claimed as browser-tested.</p><p>The initial native dialog allowed Tab to leave the document for browser chrome. Explicit focus wrapping was added, then containment, Escape and focus return passed. The Harbor light contextual-text and Harbor dark glass extremes were corrected before the final contrast run.</p><h2>Evidence files</h2><ul><li><a href="token-checks.json">Token/composite results</a></li><li><a href="browser-checks.json">Observed browser checks and limitations</a></li><li><a href="export-checks.json">Downloaded export checks</a></li><li><a href="captures/2026-09-17-focus-selection-geometry-header/README.md">Before/after visual captures: focus, selection, geometry and header</a></li><li><a href="captures/2026-09-17-cascade-layers/README.md">Cascade layers: before, after and the caught regression</a></li><li><a href="captures/2026-09-17-headless-core/README.md">Headless core: zero DOM mutation evidence</a></li><li><a href="captures/2026-09-17-rtl-and-reduced-effects/README.md">Right-to-left and reduced transparency, with the contrast regression found and fixed</a></li><li><a href="captures/2026-09-17-forced-colours/README.md">Forced colours, both palettes, with the text-backplate defect found and fixed</a></li><li><a href="frames.json">Visual regression frame set</a></li>{artifact_link}{motion_link}</ul><h2>Browser scenarios</h2><ul>{rows}</ul><h2>Historical captured previews</h2><p>These captures predate the latest Resin/Haze controls and material-driven component choreography. Use the live motion suite for the current rendering.</p><p><a href="../artifacts/crystal-motion.png">Interactive motion collection</a> · <a href="../artifacts/crystal-mirage-chromatic.png">Chromatic Mirage modal</a> · <a href="../artifacts/crystal-named-materials.png">Haze, Stone and Mirage</a> · <a href="../artifacts/crystal-content-blending.png">80% Haze over Resin</a> · <a href="../artifacts/crystal-desktop-dark.png">Desktop dark conversation</a> · <a href="../artifacts/crystal-mobile-light.png">Narrow light conversation</a> · <a href="../artifacts/crystal-material-hierarchy.png">Material studies</a></p>'''
(EVIDENCE/'report.html').write_text(shell.document(
    title='Verification', path='verification/report.html', content=content,
    main_class='doc-body', skip='Skip to the verification summary',
    footer_note='Crystal 2.0 · Reproducible evidence, bounded claims.',
    footer_link=('docs/adoption.html','Build and adoption guide')))
print('Rendered verification summary from actual check records.')
